def merge_pages(pages, limit):
    if not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid')
    seen=set(); unique=[]
    for page in pages:
        for item in page:
            if item['id'] not in seen:
                seen.add(item['id']); unique.append(dict(item))
    return sorted(unique, key=lambda x: x['created_at'], reverse=True)[:limit]

