def dependency_order(graph):
    visiting=set(); visited=set(); result=[]
    def visit(node):
        if node in visiting: raise ValueError('cycle')
        if node in visited: return
        visiting.add(node)
        for dep in graph.get(node, []): visit(dep)
        visiting.remove(node); visited.add(node); result.append(node)
    for node in graph: visit(node)
    return result

